1	/* Fringe Planner — stylesheet
2	 * Extracted/adapted from plan/design/mock.html. Brand tokens match the home
3	 * site's css/styles.css (violet #6c4cf1, ink/muted/hairline, 16px radius,
4	 * soft shadow, Plus Jakarta Sans display + Inter body, 1120px container).
5	 * This stylesheet is self-contained — the planner does not load styles.css.
6	 */
7	
8	:root {
9	  --violet: #6c4cf1;
10	  --violet-dark: #5a3fd6;
11	  --ink: #101828;
12	  --paper: #ffffff;
13	  --bg: #f7f8fa;
14	  --muted: #667085;
15	  --line: #eaecf0;
16	  --ok: #059669;
17	  --ok-text: #047857;
18	  --ok-bg: #e6f7ee;
19	  --warn: #ef4444;
20	  --shadow-soft: 0 12px 30px rgba(16, 24, 40, 0.08);
21	  --maxw: 1120px;
22	  --radius: 16px;
23	  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
24	  --display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
25	}
26	* { box-sizing: border-box; }
27	html { scroll-behavior: smooth; }
28	body {
29	  margin: 0;
30	  font-family: var(--sans);
31	  color: var(--ink);
32	  background: var(--bg);
33	  line-height: 1.5;
34	}
35	[hidden] { display: none !important; }
36	.container { width: 100%; max-width: var(--maxw); margin: 0 auto; padding-inline: 24px; }
37	a { color: inherit; }
38	.sr-only {
39	  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
40	  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
41	}
42	
43	/* ============ Header ============ */
44	.site-header {
45	  border-bottom: 1px solid var(--line);
46	  position: sticky; top: 0; z-index: 50;
47	  background: rgba(255, 255, 255, 0.95);
48	  backdrop-filter: blur(6px);
49	}
50	.header-inner { display: flex; align-items: center; height: 64px; gap: 24px; }
51	.logo {
52	  font-family: var(--display); font-weight: 700; font-size: 1.4rem;
53	  letter-spacing: -0.01em; text-decoration: none; white-space: nowrap;
54	}
55	.logo-now { color: var(--violet); }
56	.main-nav { display: flex; gap: 28px; margin-inline: auto; }
57	.nav-link {
58	  text-decoration: none; font-size: 0.98rem; padding-bottom: 2px;
59	  border-bottom: 2px solid transparent; color: var(--ink);
60	}
61	.nav-link:hover { color: var(--violet); }
62	.nav-link.is-active { color: var(--violet); border-bottom-color: var(--violet); }
63	.header-hint { font-size: 0.8rem; color: var(--muted); white-space: nowrap; }
64	
65	/* ============ Page head ============ */
66	.page-head { padding: 44px 0 8px; }
67	.page-kicker {
68	  display: inline-block; font-size: 0.72rem; font-weight: 700;
69	  letter-spacing: 0.08em; text-transform: uppercase; color: var(--violet);
70	  background: rgba(108, 76, 241, 0.09); border-radius: 999px; padding: 5px 12px;
71	  margin: 0 0 12px;
72	}
73	.page-title {
74	  font-family: var(--display); font-weight: 700; letter-spacing: -0.01em;
75	  font-size: 2.3rem; line-height: 1.12; margin: 0 0 8px;
76	}
77	.page-sub { color: var(--muted); font-size: 1.02rem; max-width: 640px; margin: 0; }
78	
79	.panel {
80	  background: var(--paper);
81	  border: 1px solid var(--line);
82	  border-radius: var(--radius);
83	  box-shadow: var(--shadow-soft);
84	}
85	
86	/* ============ Loading / error states ============ */
87	.state-panel {
88	  max-width: 660px; margin: 40px auto; padding: 40px 32px;
89	  text-align: center; border-radius: var(--radius);
90	  background: var(--paper); border: 1px solid var(--line); box-shadow: var(--shadow-soft);
91	}
92	.state-spinner {
93	  width: 34px; height: 34px; margin: 0 auto 16px; border-radius: 50%;
94	  border: 3px solid var(--line); border-top-color: var(--violet);
95	  animation: spin 0.8s linear infinite;
96	}
97	@keyframes spin { to { transform: rotate(360deg); } }
98	.state-title { font-family: var(--display); font-weight: 700; font-size: 1.15rem; margin: 0 0 6px; }
99	.state-sub { color: var(--muted); font-size: 0.92rem; margin: 0; }
100	.state-error .state-icon {
101	  width: 44px; height: 44px; margin: 0 auto 14px; border-radius: 50%;
102	  display: grid; place-items: center; color: var(--warn); background: rgba(239, 68, 68, 0.1);
103	}
104	.state-error .btn { margin-top: 16px; }
105	
106	/* ============ Screen 1 — Input ============ */
107	.intake { max-width: 660px; margin: 0 auto; padding: 36px 40px 30px; }
108	.step-kicker {
109	  font-size: 0.72rem; font-weight: 700; letter-spacing: 0.08em;
110	  text-transform: uppercase; color: var(--violet); margin: 0 0 6px;
111	}
112	.intake-title {
113	  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
114	  letter-spacing: -0.01em; margin: 0 0 6px;
115	}
116	.intake-sub { color: var(--muted); font-size: 0.95rem; margin: 0 0 22px; }
117	.intake-sub .crumbs { color: var(--ink); font-weight: 600; white-space: nowrap; }
118	.intake-sub .crumb-sep { color: #b6bdc9; padding-inline: 2px; }
119	
120	.dropzone {
121	  display: flex; flex-direction: column; align-items: center; gap: 6px;
122	  text-align: center; padding: 34px 24px 30px;
123	  border: 2px dashed #d5d9e2; border-radius: var(--radius);
124	  background: #fbfbfd;
125	  transition: border-color 0.15s ease, background 0.15s ease;
126	  cursor: pointer;
127	}
128	.dropzone:hover, .dropzone:focus-within, .dropzone.is-dragover {
129	  border-color: var(--violet); background: rgba(108, 76, 241, 0.04);
130	}
131	.dz-icon {
132	  width: 46px; height: 46px; display: grid; place-items: center;
133	  color: var(--violet); background: rgba(108, 76, 241, 0.1);
134	  border-radius: 14px; margin-bottom: 6px;
135	}
136	.dz-line1 { font-weight: 700; font-size: 1.02rem; }
137	.dz-line2 { color: var(--muted); font-size: 0.85rem; margin-bottom: 12px; }
138	.btn {
139	  display: inline-flex; align-items: center; gap: 8px;
140	  font: inherit; font-weight: 700; font-size: 0.95rem;
141	  border: none; border-radius: 12px; padding: 12px 22px; cursor: pointer;
142	  color: #fff; background: var(--violet);
143	  box-shadow: 0 8px 20px rgba(108, 76, 241, 0.28);
144	  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
145	  text-decoration: none;
146	}
147	.btn:hover { background: var(--violet-dark); transform: translateY(-1px); }
148	.btn:focus-visible { outline: 3px solid var(--violet); outline-offset: 3px; }
149	.btn:disabled { opacity: 0.55; cursor: not-allowed; transform: none; }
150	.dz-alt { margin-top: 12px; font-size: 0.85rem; color: var(--muted); }
151	.link-quiet {
152	  font-weight: 700; color: var(--violet-dark); text-decoration: none;
153	  border-bottom: 1px solid rgba(108, 76, 241, 0.35);
154	  background: none; border-top: none; border-left: none; border-right: none;
155	  font: inherit; cursor: pointer; padding: 0;
156	}
157	.link-quiet:hover { color: var(--violet); border-bottom-color: var(--violet); }
158	
159	/* Upload summary */
160	.statecap {
161	  margin: 22px 0 8px; font-size: 0.64rem; font-weight: 700;
162	  letter-spacing: 0.1em; text-transform: uppercase; color: #98a2b3;
163	}
164	.upload-summary {
165	  display: flex; align-items: center; gap: 14px;
166	  border: 1px solid #c7ecd9; background: var(--ok-bg);
167	  border-radius: 12px; padding: 13px 16px;
168	}
169	.upload-summary.is-partial { border-color: #fde3b8; background: #fff8ea; }
170	.us-tick {
171	  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 50%;
172	  display: grid; place-items: center; color: #fff; background: var(--ok);
173	}
174	.us-body { flex: 1; min-width: 0; }
175	.us-main { font-weight: 700; font-size: 0.95rem; color: var(--ok-text); }
176	.us-sub { font-size: 0.8rem; color: var(--muted); }
177	.us-file {
178	  flex: 0 0 auto; font-size: 0.74rem; font-weight: 600; color: var(--muted);
179	  background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px;
180	  white-space: nowrap;
181	}
182	.missing-list {
183	  margin: 8px 0 0; padding: 10px 14px; list-style: none;
184	  border: 1px solid var(--line); border-radius: 10px; background: #fff;
185	  font-size: 0.82rem; color: var(--muted); max-height: 160px; overflow-y: auto;
186	}
187	.missing-list li { padding: 2px 0; }
188	.missing-list code { font-size: 0.8rem; color: var(--ink); }
189	
190	.continue-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 18px; flex-wrap: wrap; }
191	.continue-note { font-size: 0.82rem; color: var(--muted); }
192	
193	/* Collapsed "More settings" placeholder */
194	.more { margin-top: 22px; border-top: 1px solid var(--line); padding-top: 6px; }
195	.more summary {
196	  display: flex; align-items: center; gap: 8px; list-style: none;
197	  cursor: pointer; padding: 10px 4px; font-weight: 700; font-size: 0.9rem; color: var(--ink);
198	  border-radius: 8px;
199	}
200	.more summary::-webkit-details-marker { display: none; }
201	.more summary:hover { color: var(--violet-dark); }
202	.more summary:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
203	.more-caret { transition: transform 0.15s ease; color: var(--muted); font-size: 0.7rem; }
204	.more[open] .more-caret { transform: rotate(180deg); }
205	.more-hint { margin-left: auto; font-weight: 600; font-size: 0.74rem; color: #98a2b3; }
206	.more-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 22px; padding: 8px 4px 14px; }
207	.more-field-label {
208	  display: block; text-transform: uppercase; letter-spacing: 0.05em;
209	  font-size: 0.68rem; font-weight: 700; color: var(--muted); margin: 0 0 7px;
210	}
211	.chips { display: flex; flex-wrap: wrap; gap: 6px; grid-column: 1 / -1; }
212	.chips-wrap { grid-column: 1 / -1; }
213	.chip {
214	  font-size: 0.78rem; font-weight: 600; padding: 6px 12px; border-radius: 999px;
215	  border: 1px solid var(--line); background: #fff; color: var(--muted);
216	}
217	.chip.is-on { border-color: var(--violet); color: var(--violet-dark); background: rgba(108, 76, 241, 0.07); }
218	.faux-input {
219	  display: flex; align-items: center; justify-content: space-between; gap: 8px;
220	  font-size: 0.88rem; font-weight: 600;
221	  border: 1px solid var(--line); border-radius: 10px; background: #fff;
222	  padding: 9px 12px; color: var(--ink);
223	}
224	.faux-input .fi-caret { color: var(--muted); font-size: 0.68rem; }
225	
226	/* ============ Screen 2 — Availability calendar ============ */
227	.cal-card { padding: 30px 28px 26px; }
228	.cal-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; flex-wrap: wrap; }
229	.cal-title {
230	  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
231	  letter-spacing: -0.01em; margin: 0 0 6px;
232	}
233	.cal-sub { color: var(--muted); font-size: 0.92rem; margin: 0; max-width: 520px; }
234	
235	/* The payoff number */
236	.hero-count { text-align: right; flex: 0 0 auto; }
237	.hc-num {
238	  font-weight: 800; font-size: 3.1rem; line-height: 1; letter-spacing: -0.02em;
239	  color: var(--violet-dark); white-space: nowrap;
240	}
241	.hc-num .hc-of { color: #b7bcc9; font-weight: 700; font-size: 2rem; }
242	.hc-num.bump { animation: countbump 0.4s ease; }
243	@keyframes countbump {
244	  0% { transform: scale(1); }
245	  45% { transform: scale(1.09); color: var(--violet); }
246	  100% { transform: scale(1); }
247	}
248	.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
249	.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }
250	
251	/* Toolbar: legend on the left, time-of-day range on the right */
252	.cal-toolbar {
253	  display: flex; align-items: flex-end; justify-content: space-between; gap: 28px;
254	  margin: 22px 0 6px; padding-top: 18px; border-top: 1px solid var(--line);
255	  flex-wrap: wrap;
256	}
257	.legend { display: flex; gap: 18px; flex-wrap: wrap; padding-bottom: 10px; }
258	.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.78rem; color: var(--muted); }
259	.lg i { width: 16px; height: 10px; border-radius: 3px; display: block; }
260	.lg-av i { background: var(--violet); }
261	.lg-sold i { background: transparent; border: 1.5px solid #c6cdda; }
262	.lg-dim i { background: var(--violet); opacity: 0.22; }
263	
264	/* Time-of-day dual-handle slider */
265	.tod { flex: 0 0 400px; max-width: 100%; }
266	.tod-label {
267	  display: flex; justify-content: space-between; align-items: baseline;
268	  font-size: 0.72rem; font-weight: 700; letter-spacing: 0.05em;
269	  text-transform: uppercase; color: var(--muted); margin-bottom: 20px;
270	}
271	.tod-value { font-weight: 700; letter-spacing: 0; text-transform: none; font-size: 0.82rem; color: var(--ink); font-variant-numeric: tabular-nums; }
272	.tslider { position: relative; height: 20px; }
273	.ts-track {
274	  position: absolute; left: 0; right: 0; top: 50%; height: 6px;
275	  transform: translateY(-50%); border-radius: 999px; background: #e7e9f0;
276	}
277	.ts-fill {
278	  position: absolute; top: 50%; height: 6px; transform: translateY(-50%);
279	  border-radius: 999px; background: var(--violet);
280	}
281	.ts-handle {
282	  position: absolute; top: 50%; width: 20px; height: 20px;
283	  transform: translate(-50%, -50%); border-radius: 50%;
284	  background: #fff; border: 2px solid var(--violet);
285	  box-shadow: 0 2px 6px rgba(16, 24, 40, 0.18);
286	  cursor: grab; touch-action: none; z-index: 2;
287	}
288	.ts-handle:active { cursor: grabbing; transform: translate(-50%, -50%) scale(1.12); }
289	.ts-handle:focus-visible { outline: 3px solid rgba(108, 76, 241, 0.45); outline-offset: 2px; }
290	.ts-bubble {
291	  position: absolute; bottom: 24px; transform: translateX(-50%);
292	  font-size: 0.72rem; font-weight: 700; color: var(--violet-dark);
293	  background: rgba(108, 76, 241, 0.09); border-radius: 6px; padding: 2px 7px;
294	  white-space: nowrap; font-variant-numeric: tabular-nums; pointer-events: none;
295	}
296	.ts-scale {
297	  display: flex; justify-content: space-between; margin-top: 8px;
298	  font-size: 0.66rem; color: #98a2b3; font-variant-numeric: tabular-nums;
299	}
300	
301	/* --- The calendar canvas --- */
302	/* .cal-wrap is the scroll container: day-header stays sticky at its top while
303	   the lane list scrolls beneath it. The toolbar/hero-count above are outside
304	   this container entirely, so they never scroll away either. */
305	.cal-wrap {
306	  position: relative; margin-top: 14px;
307	  max-height: 62vh; overflow-y: auto; overflow-x: hidden;
308	  border-radius: 10px;
309	}
310	.cal-inner { position: relative; padding-top: 40px; /* room for the handle flags */ }
311	
312	.cal-row { display: grid; grid-template-columns: 248px 1fr 118px; gap: 0 14px; align-items: center; }
313	
314	.cal-head {
315	  border-bottom: 1px solid var(--line); padding-bottom: 6px;
316	  position: sticky; top: 0; z-index: 4; background: var(--paper);
317	}
318	.cal-head-left { font-size: 0.72rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--muted); }
319	.cal-head-right { font-size: 0.68rem; font-weight: 600; color: #98a2b3; text-align: left; }
320	.days { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; }
321	.day-col { text-align: center; line-height: 1.15; }
322	.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
323	.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
324	.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
325	.day-col.post .day-num, .day-col.post .day-dow { color: #cfd4de; }
326	
327	.lanes { position: relative; z-index: 1; }
328	.lane { min-height: 52px; padding: 5px 0; border-bottom: 1px solid #f1f2f6; }
329	.lane:last-child { border-bottom: none; }
330	.lane-label { min-width: 0; }
331	.lane-title {
332	  font-family: var(--display); font-weight: 600; font-size: 0.92rem; line-height: 1.2;
333	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
334	}
335	.lane-meta {
336	  font-size: 0.72rem; color: var(--muted); line-height: 1.3;
337	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
338	}
339	.lane-meta .lm-time { font-weight: 700; color: var(--ink); font-variant-numeric: tabular-nums; }
340	.lane-track { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; align-items: center; height: 100%; }
341	.cell { height: 12px; border-radius: 4px; }
342	.cell-av { background: var(--violet); }
343	.cell-sold { background: transparent; border: 1.5px solid #c6cdda; }
344	.lane-status { font-size: 0.74rem; line-height: 1.3; }
345	.lane-status .st-ok { font-weight: 700; color: var(--ok-text); }
346	.lane-status .st-why { color: var(--muted); }
347	/* A show with nothing catchable recedes as a whole */
348	.lane--out .lane-title, .lane--out .lane-meta { opacity: 0.42; }
349	.lane--out .cell-av { background: #c4c9d6; }
350	
351	/* --- Window overlay: dim panels, highlight band, drag handles --- */
352	.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
353	.festend { position: absolute; top: 40px; bottom: 0; background: rgba(234, 236, 240, 0.35); border-left: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
