const shows=require('./data/normalized/shows.json');
// find shows that have at least one day with 2+ performances in August
function augDoubles(sh){
  const byDay={};
  for(const p of sh.performances||[]){ if(!/^2026-08-/.test(p.date))continue; (byDay[p.date]=byDay[p.date]||[]).push(p); }
  return Object.values(byDay).some(a=>a.length>=2);
}
const withDouble=shows.filter(augDoubles);
// also collect variety of statuses
const picks=[];
for(const sh of withDouble){ if(picks.length>=10)break; picks.push(sh.slug); }
// add some single-perf variety incl statuses
const statusesWanted=['TWO_FOR_ONE','PREVIEW_SHOW','FREE_TICKETED','EVENT_SPECIFIC','NO_ALLOCATION_CONTACT_VENUE','FREE_NON_TICKETED'];
for(const st of statusesWanted){
  const sh=shows.find(s=>(s.performances||[]).some(p=>p.status===st));
  if(sh&&!picks.includes(sh.slug))picks.push(sh.slug);
}
console.log('withDouble total:',withDouble.length);
require('fs').writeFileSync('/tmp/claude-0/-home-user/e0e5397f-4fe0-5171-b832-393508793723/scratchpad/fav.txt', picks.join('\n')+'\n');
console.log(picks.join('\n'));
"

